python_code: ```python
def solveSudoku(board):
    def isValid(row, col, val, board):
        n = len(board)
        for i in range(n):
            if board[row][i] == val:
                return False
        for i in range(n):
            if board[i][col] == val:
                return False

        startRow = (row // 3) * 3
        startCol = (col // 3) * 3

        for i in range(startRow, startRow + 3):
            for j in range(startCol, startCol + 3):
                if board[i][j] == val:
                    return False

        return True

    def backTracking():
        for i in range(len(board)):
            for j in range(len(board[0])):
                if board[i][j] != '.':
                    continue
                for val in range(1, 10):
                    if isValid(i, j, str(val), board):
                        board[i][j] = str(val)
                        if backTracking():
                            return True
                        board[i][j] = '.'
                return False
        return True

    backTracking()
    return board

def main(case_input):
    # Make a deep copy to avoid modifying the input
    board_copy = [row[:] for row in case_input]
    result = solveSudoku(board_copy)
    return result
