      "param": {
        "variables": [["excel_file", "file"], ["chart_type", "string"]]
      }
    },
    {
      "id": "2",
      "type": "code",
      "param": {
        "variables": [["excel_file", ["excel_file", "1"]]],
        "outputs": [["json_data", "string"]],
        "code": "def main(excel_file):
	import pandas as pd
	import json

	# Read Excel file into DataFrame (first sheet only)
	df = pd.read_excel(excel_file)

	# Convert to JSON string with records orientation
	json_result = df.to_json(orient='records', force_ascii=False, indent=2)

	return {"json_data": json_result}"
      }
    },
    {
      "id": "3",
      "type": "if-else",
      "param": {
        "cases": [
          [null, [[["chart_type", "1"], "not empty"]]],
          [null, [[["chart_type", "1"], "empty"]]]
        ]
      }
    },
    {
      "id": "4",
      "type": "code",
      "param": {
        "variables": [
          ["json_data", ["json_data", "2"]],
          ["chart_type", ["chart_type", "1"]]
        ],
        "outputs": [["result", "string"]],
        "code": "def main(json_data: str, chart_type: str):
	import json

	# Parse JSON data
	try:
		data = json.loads(json_data)
	except:
		return {"result": "Invalid JSON data"}

	if not data:
		return {"result": "No data to chart"}

	# Get column names
	columns = list(data[0].keys())
	if len(columns) < 2:
		return {"result": "Insufficient columns for charting"}

	# Find numeric columns
	numeric_cols = []
	for col in columns:
		try:
			# Try to convert first non-null value to float
			for row in data:
				if row[col] is not None and str(row[col]).strip():
					float(str(row[col]).replace(',', ''))
					numeric_cols.append(col)
					break
		except:
			continue

	if not numeric_cols:
		return {"result": "No numeric columns found for charting"}

	# Use first column as category, first numeric column as value
	cat_col = columns[0]
	val_col = numeric_cols[0]

	# Extract categories and values
	categories = []
	values = []
	for row in data:
		if row[cat_col] is not None and row[val_col] is not None:
			categories.append(str(row[cat_col]))
			# Clean numeric value (remove commas)
			val_str = str(row[val_col]).replace(',', '').strip()
			try:
				values.append(float(val_str))
			except:
				continue

	if not categories or not values:
		return {"result": "No valid data for charting"}

	# Generate ECharts option
	if chart_type == "pie":
		data_pairs = [{"name": cat, "value": val} for cat, val in zip(categories, values)]
		option = {
			"title": {"text": f"{val_col} by {cat_col}"},
			"tooltip": {"trigger": "item"},
			"series": [{
				"name": val_col,
				"type": "pie",
				"radius": "50%",
				"data": data_pairs
			}]
		}
	elif chart_type in ["bar", "line"]:
		option = {
			"title": {"text": f"{val_col} by {cat_col}"},
			"tooltip": {},
			"legend": {},
			"xAxis": {"type": "category", "data": categories},
			"yAxis": {"type": "value"},
			"series": [{
				"name": val_col,
				"type": chart_type,
				"data": values
			}]
		}
	else:
		return {"result": f"Unsupported chart type: {chart_type}"}

	return {"result": json.dumps(option, indent=2, ensure_ascii=False)}"
      }
