	import json

	try:
		data = json.loads(api_response)
		tree = data.get('tree', [])

		if not tree:
			return {"file_structure": "No files found or invalid repository"}

		# Build tree structure
		structure = {}
		for item in tree:
			path = item['path']
			parts = path.split('/')
			current = structure
			for part in parts[:-1]:
				if part not in current:
					current[part] = {}
				current = current[part]
			if parts:
				current[parts[-1]] = item['type']  # 'blob' for file, 'tree' for dir

		# Format as tree
		def format_tree(node, prefix=""):
			result = []
			items = sorted(node.items())
			for i, (name, value) in enumerate(items):
				is_last = i == len(items) - 1
				if isinstance(value, dict):
					result.append(f"{prefix}{'└── ' if is_last else '├── '}{name}/")
					result.extend(format_tree(value, prefix + ('    ' if is_last else '│   ')))
				else:
					result.append(f"{prefix}{'└── ' if is_last else '├── '}{name}")
			return result

		formatted_structure = '\n'.join(format_tree(structure))
		return {"file_structure": formatted_structure}

	except json.JSONDecodeError:
		return {"file_structure": "Error: Invalid API response"}
	except Exception as e:
		return {"file_structure": f"Error: {str(e)}"}"
